def ph(s: str):
    return sorted(re.findall(r"\{(\w+)\}", s))

ok = True
for k, v in S.items():
    if len(v) != len(LANGS):
        print("BAD LEN", k, len(v))
        ok = False
        continue
    base = ph(v[0])
    for lang, txt in zip(LANGS, v):
        if not txt.strip():
            print("EMPTY", k, lang)
            ok = False
        if ph(txt) != base:
            print("PLACEHOLDER MISMATCH", k, lang)
            ok = False
if not ok:
    sys.exit(1)


def esc(s: str) -> str:
    return s.replace("\\", "\\\\").replace('"', '\\"').replace("$", "\\$")


out = [
    "// GENERATED by tools/gen_strings.py — edit that file, not this one.\n\n",
    "const Map<String, Map<String, String>> kStrings = {\n",
]
for i, lang in enumerate(LANGS):
    out.append(f"  '{lang}': {{\n")
    for k, v in S.items():
        out.append(f'    \'{k}\': "{esc(v[i])}",\n')
    out.append("  },\n")
out.append("};\n")

target = pathlib.Path(__file__).resolve().parent.parent / "lib" / "core" / "strings.dart"
target.write_text("".join(out), encoding="utf-8")
print(f"OK: {len(S)} keys x {len(LANGS)} languages -> {target}")
